            }
        }
    },
    {
        "id": "endCool",
        "type": "core.control.end",
        "typeVersion": "1.0",
        "display": {"label": "End (cool)"},
        "inputs": {},
        "outputs": {
            "result": {
                "source": "=js:'cool'"
            }
        }
    }
]

flow['edges'] = [
    {
        "id": "edge_start_output_checkTemperature_input",
        "sourceNodeId": "start",
        "sourcePort": "output",
        "targetNodeId": "checkTemperature",
        "targetPort": "input"
    },
    {
        "id": "edge_checkTemperature_true_endWarm_input",
        "sourceNodeId": "checkTemperature",
        "sourcePort": "true",
        "targetNodeId": "endWarm",
        "targetPort": "input"
    },
    {
        "id": "edge_checkTemperature_false_endCool_input",
        "sourceNodeId": "checkTemperature",
        "sourcePort": "false",
        "targetNodeId": "endCool",
        "targetPort": "input"
    }
]

